// 笔压：有一段落笔更重\n      g.append(sv('circle', { class: 'dl-ring-c', cx: 50, cy: 50, r: f1(r), stroke: paint, 'stroke-width': f1(w * 1.55), 'stroke-dasharray': `${f1(C * 0.28)} ${f1(C * 0.72)}`, 'stroke-dashoffset': f1(-C * (0.22 + 0.11 * i)), 'stroke-linecap': 'round' }));\n    }\n    if (st.金纹数) {\n      const k = Math.min(st.金纹数, 9), dl = Math.min(C * 0.05, (C / k) * 0.5);\n      g.append(sv('circle', { class: 'dl-ring-g', cx: 50, cy: 50, r: f1(r), 'stroke-width': f1(Math.max(w * 0.62, 0.6)), 'stroke-dasharray': `${f1(dl)} ${f1(C / k - dl)}` }));\n    }\n    if (theme === 'senlin' && live && !rg.潜在) g.append(sv('circle', { class: 'dl-ring-b', cx: 50, cy: f1(50 - r), r: f1(Math.max(w * 0.85, 1.1)), fill: '#F2FFF8' }));\n    return g;\n  }\n  // 头像图：玩家上传或链接 > 玩家选的头像变体 > 头像库自动挑 > 没有（画程序生成的）。头像库由“斗罗头像”脚本挂在 window.DLAvatars\n  function libraryFace(p) {\n    const lib = window.DLAvatars, mine = state.settings.avatars[p.姓名];\n    if (!lib || !p.姓名) return null;\n    const ctx = { part: state.stat && state.stat.时空 ? state.stat.时空.当前部 : null, age: p.年龄, choice: mine && mine.pick };\n    // 同一人此刻换了叫法（斗3 的娜儿、古月）时，先找那个叫法自己的图\n    const nm = shownName(p);\n    return (nm && nm !== p.姓名 ? lib.pick(nm, ctx) : null) || lib.pick(p.姓名, ctx);\n  }\n  function avatarSrc(p) {\n    const mine = state.settings.avatars[p.姓名];\n    if (mine && mine.src) return mine.src;\n    const hit = libraryFace(p);\n    return hit ? hit.src : null;\n  }\n  function avatarEl(p, o = {}) {\n    const theme = state.theme;\n    const rings = o.rings === false ? [] : ringsOf(p);\n    const n = rings.length;\n    const a = n ? Math.max(23, 45 - n * 3.3 - 2) : 42;\n    const pitch = n ? Math.min(3.3, (46.5 - a - 1.5) / n) : 0;\n    const w = Math.max(pitch * 0.56, 0.95);\n    const top = n ? ringStyle(topRing(rings), theme) : null;\n    const tint = top ? top.主色 : '#8C8676';\n    const src = avatarSrc(p);\n    const id = 'dl-avc' + ++avSeq;\n    const soul = activeSoul(p);\n    const kind = isBeastForm(p) || (so